import{_ as t,o as a,c as s,ak as i}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"AI provider","description":"Connect an LLM to the dashboard: Anthropic, OpenAI, a local OpenAI-compatible model or the Claude Code CLI, with model roles, response language and token limits.","frontmatter":{"title":"AI provider","description":"Connect an LLM to the dashboard: Anthropic, OpenAI, a local OpenAI-compatible model or the Claude Code CLI, with model roles, response language and token limits.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/ai-provider.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/ai-provider.html"}],["meta",{"property":"og:title","content":"AI provider | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Connect an LLM to the dashboard: Anthropic, OpenAI, a local OpenAI-compatible model or the Claude Code CLI, with model roles, response language and token limits."}]]},"headers":[],"relativePath":"guide/ai-provider.md","filePath":"guide/ai-provider.md","lastUpdated":1790921321000}'),o={name:"guide/ai-provider.md"};function n(r,e,d,l,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="ai-provider" tabindex="-1">AI provider <a class="header-anchor" href="#ai-provider" aria-label="Permalink to &quot;AI provider&quot;">​</a></h1><p>Piwi works without a model. Connect one and it powers <a href="/features/ai-diagnosis.html">AI diagnosis</a> (the explanation of a failure cluster or a single execution, and the cluster titles), semantic merging of failure clusters, the <strong>Fixed before</strong> matches of <a href="/features/fix-plans.html#fixed-before">fix plans</a>, the authoring of <a href="/features/ai-steps.html">AI steps</a> and the AI narrative of <a href="/features/quality-reports.html">quality reports</a>. All of them use the same provider, configured once on the server; API keys never leave it.</p><h2 id="enabling-ai-diagnosis" tabindex="-1">Enabling AI diagnosis <a class="header-anchor" href="#enabling-ai-diagnosis" aria-label="Permalink to &quot;Enabling AI diagnosis&quot;">​</a></h2><p>Configure a provider via <strong>Settings → AI</strong>, or with environment variables. <code>PIWI_AI_PROVIDER</code> is the switch: once it is set, the provider configuration comes from the environment and the UI shows its provider, key and base URL read-only. A model or temperature picked in the UI still overrides the env one, and a role the environment leaves out can be turned on in the UI by reusing a role it sets. Without <code>PIWI_AI_PROVIDER</code>, the other provider variables below are not read.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>PIWI_AI_PROVIDER</code></td><td><code>anthropic</code>, <code>openai</code>, or <code>claude-cli</code></td></tr><tr><td><code>PIWI_AI_API_KEY</code></td><td>Provider API key (stored encrypted when set via the UI; never returned by the API)</td></tr><tr><td><code>PIWI_AI_MODEL</code></td><td>Model name (default: <code>claude-opus-4-8</code> for Anthropic)</td></tr><tr><td><code>PIWI_AI_BASE_URL</code></td><td>Base URL of the provider API: required for <code>openai</code>, OpenAI itself (<code>https://api.openai.com/v1</code>) included; optional for <code>anthropic</code> (a gateway or proxy)</td></tr><tr><td><code>PIWI_AI_AUTO_DIAGNOSE</code></td><td><code>true</code> to diagnose, when a run finishes, the clusters that failed in it and have no completed diagnosis yet</td></tr><tr><td><code>PIWI_AI_AUTO_DIAGNOSE_MAX</code></td><td>Max clusters auto-diagnosed per finished run (budget cap; default <code>3</code>)</td></tr><tr><td><code>PIWI_AI_RESEARCH_MODEL</code> / <code>_PROVIDER</code> / <code>_BASE_URL</code> / <code>_API_KEY</code></td><td>Optional <strong>research</strong> model for two-stage diagnosis; provider/base URL/key default to the main ones</td></tr><tr><td><code>PIWI_AI_EMBEDDING_PROVIDER</code> / <code>_MODEL</code> / <code>_BASE_URL</code> / <code>_API_KEY</code></td><td>Optional <strong>embedding</strong> model for semantic failure clustering (OpenAI-compatible only: Anthropic has no embeddings API)</td></tr></tbody></table><p>A saved key is sent only to the provider and base URL it was saved for: pointing a role at another base URL in <strong>Settings → AI</strong>, or testing one there, needs the key entered again.</p><p>The <a href="/reference/configuration.html#ai-diagnosis">Configuration reference</a> lists every AI variable.</p><p>When a run finishes and <code>PIWI_AI_AUTO_DIAGNOSE</code> is on, the <code>PIWI_AI_AUTO_DIAGNOSE_MAX</code> budget is spent where it buys the most. The run&#39;s clusters are ordered by their representative failing execution&#39;s top <a href="/features/evidence.html#clues">clue</a>: a cluster whose failure carries <strong>no deterministic clue</strong> (the one the model has to reason about from scratch) goes first, then the ones with only a weak clue, and only then a failure a strong clue already explains, with the newest cluster breaking ties. A cluster that already has a completed or a running diagnosis is left out before the ordering, so a recurring, already-diagnosed cluster never takes one of the slots.</p><h3 id="streaming-diagnosis" tabindex="-1">Streaming diagnosis <a class="header-anchor" href="#streaming-diagnosis" aria-label="Permalink to &quot;Streaming diagnosis&quot;">​</a></h3><p>A diagnosis streams: the model&#39;s reasoning appears in a live panel as it arrives, with a stage indicator (<em>Researching patterns</em> while a <a href="#model-roles">research model</a> pre-analyzes the failure, when one is configured, then <em>Diagnosing root cause</em>), and turns into the result card when it completes. The <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a> describe the streaming protocol (the in-app reference at <code>/docs</code> shows the same spec).</p><p>To be told when a diagnosis finishes without watching the panel, turn on <strong>Settings → AI → Diagnosis notifications</strong>: a per-browser preference (stored on that device only) that shows a browser notification on completion once you grant the permission.</p><h2 id="model-roles" tabindex="-1">Model roles <a class="header-anchor" href="#model-roles" aria-label="Permalink to &quot;Model roles&quot;">​</a></h2><p>Piwi calls models in up to three distinct roles, each with its own complete provider configuration (or a <strong>reuse</strong> pointer to inherit another role&#39;s provider and credentials):</p><ul><li><strong>Diagnosis</strong>: the main model that writes the final diagnosis (required to enable AI). The quality report narrative uses it too.</li><li><strong>Research</strong>: an optional cheaper, faster model that pre-analyzes the failure first (<em>two-stage diagnosis</em>).</li><li><strong>Embedding</strong>: an optional embeddings model that powers semantic failure clustering and the <strong>Fixed before</strong> similarity.</li></ul><p>Configure each role in <strong>Settings → AI → Model providers</strong>. A role set to <em>reuse</em> another role uses that role&#39;s provider, key, and base URL (only its model can differ), so you don&#39;t re-enter credentials for, say, a Haiku research pass on the same Anthropic key.</p><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><p><strong>Anthropic (recommended)</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_PROVIDER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-ant-...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">claude-opus-4-8</span></span></code></pre></div><p><strong>OpenAI</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_PROVIDER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openai</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.openai.com/v1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gpt-4o</span></span></code></pre></div><p><strong>OpenAI-compatible or local (Ollama, LM Studio, vLLM)</strong>: set the provider to <code>openai</code> and point the base URL at the local endpoint:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_PROVIDER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openai</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:11434/v1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">llama3.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ollama</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # optional: sent only when set, for servers that check one</span></span></code></pre></div><p>A local model keeps every diagnosis on your own infrastructure; see <a href="./privacy.html">Privacy &amp; data flow</a>.</p><p><strong>Claude Code CLI (local, no API key)</strong>: in the <a href="/features/desktop.html">desktop app</a>, pick <strong>Claude Code (local)</strong>. It runs the local <code>claude</code> CLI with your Claude Code sign-in, so <strong>Settings → AI</strong> manages sign-in and shows a live usage tally. Every role but embeddings can use it; <code>PIWI_CLAUDE_CLI_PATH</code> overrides the path.</p><p>Each role&#39;s form in <strong>Settings → AI</strong> has a <strong>Test connection</strong> button that checks its provider. The dashboard shows its AI actions only once a provider is configured.</p><h2 id="response-language" tabindex="-1">Response language <a class="header-anchor" href="#response-language" aria-label="Permalink to &quot;Response language&quot;">​</a></h2><p>Set a <strong>response language</strong> and every free-text field a person reads (summary, root cause, evidence, fix description and AI-generated cluster titles) comes back in that language, while code, locators, paths and error text stay verbatim. Set it instance-wide in Settings → AI (or <a href="/reference/configuration.html"><code>PIWI_AI_LANGUAGE</code></a>, e.g. <code>French</code>, which locks the field), and override it per project under Project → Settings → AI diagnosis. This is what makes a French ticket&#39;s <em>Most likely</em> section French: the ticket&#39;s copy follows the <a href="/features/issue-tracking.html#language">destination&#39;s language</a> and the prose follows this setting. Unset, responses are in English.</p><h2 id="context-limits-and-token-cost" tabindex="-1">Context limits (and token cost) <a class="header-anchor" href="#context-limits-and-token-cost" aria-label="Permalink to &quot;Context limits (and token cost)&quot;">​</a></h2><p>Every piece of evidence sent to the model costs tokens. Piwi caps each input so diagnoses stay fast and affordable. Override the caps in <strong>Settings → AI</strong> or via env (env wins; the UI then shows the field read-only).</p><p>The full list of <code>PIWI_AI_MAX_*</code> limit variables, their defaults and their clamping ranges lives in the <a href="/reference/configuration.html#ai-context-limits">Configuration reference → AI context limits</a>, generated from the same registry the server reads. The diagnosis context preview (<strong>Context sent to AI</strong>) shows what was trimmed to fit before you spend tokens.</p><p>Screenshots are the one input a provider can refuse outright: many self-hosted and gateway models are text-only and reject a request that carries images. Piwi retries that call without them, so the diagnosis still runs on the text evidence. Setting <code>PIWI_AI_MAX_IMAGES=0</code> skips the rejected first attempt.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/ai-diagnosis.html">AI diagnosis</a>: what a diagnosis contains and how to run one</li><li><a href="./source-control.html">Source control</a>: the diffs and source files a diagnosis reads</li><li><a href="./privacy.html">Privacy &amp; data flow</a>: exactly what a diagnosis sends, and where</li><li><a href="/reference/configuration.html#ai-diagnosis">Configuration reference</a>: every AI variable</li></ul>`,33)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
